import os
import json
import logging
from pathlib import Path
import pandas as pd
from utils.logging import setup_logger

# Ensure output directory exists
OUTPUT_DIR = Path("data/processed/behavioral")
OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
OUTPUT_PATH = OUTPUT_DIR / "power_metrics.json"
RETENTION_INPUT = Path("data/processed/behavioral/retention_metrics.json")

def load_retention_metrics():
    """Load retention metrics from the JSON file generated by T003."""
    if not RETENTION_INPUT.exists():
        raise FileNotFoundError(
            f"Retention metrics file not found: {RETENTION_INPUT}. "
            "Please ensure T003 has been completed successfully."
        )
    with open(RETENTION_INPUT, "r") as f:
        return json.load(f)

def check_power(retention_data, threshold=50):
    """
    Calculate the number of retained subjects (N) and compare against the threshold.
    
    Args:
        retention_data (dict): Data from retention_metrics.json containing 'retained_subjects'.
        threshold (int): Minimum number of subjects required (default 50).
        
    Returns:
        dict: Contains n_subjects, threshold, and meets_threshold boolean.
    """
    n_subjects = retention_data.get("retained_subjects", 0)
    meets_threshold = n_subjects >= threshold
    
    return {
        "n_subjects": n_subjects,
        "threshold": threshold,
        "meets_threshold": meets_threshold
    }

def save_power_check_results(power_data):
    """Save the power check results to the output JSON file."""
    with open(OUTPUT_PATH, "w") as f:
        json.dump(power_data, f, indent=2)
    logging.info(f"Power metrics saved to {OUTPUT_PATH}")

def main():
    """Main entry point for the power calculation task."""
    # Setup logger
    logger = setup_logger("power_check", level=logging.INFO)
    
    try:
        logger.info(f"Loading retention metrics from {RETENTION_INPUT}")
        retention_data = load_retention_metrics()
        
        logger.info("Calculating power metrics...")
        power_data = check_power(retention_data)
        
        logger.info(f"N subjects: {power_data['n_subjects']}, Threshold: {power_data['threshold']}")
        if power_data['meets_threshold']:
            logger.info("Power check PASSED: N >= threshold")
        else:
            logger.warning(f"Power check FAILED: N ({power_data['n_subjects']}) < threshold ({power_data['threshold']})")
        
        save_power_check_results(power_data)
        
        return 0
    except FileNotFoundError as e:
        logger.error(str(e))
        return 1
    except Exception as e:
        logger.exception(f"An error occurred during power calculation: {e}")
        return 1

if __name__ == "__main__":
    exit(main())
